import { useState, useEffect } from "react";

// Giả lập một API mất 300ms để trả dữ liệu
function getPosts() {
  return new Promise((resolve) =>
    setTimeout(() => resolve([{ id: 1, title: "Bài viết 1" }, { id: 2, title: "Bài viết 2" }]), 300)
  );
}

export default function App() {
  const [posts, setPosts] = useState(null);

  useEffect(() => {
    getPosts().then(setPosts);
  }, []);

  if (!posts) return <p id="status">Đang tải...</p>;
  return (
    <ul id="list">
      {posts.map((p) => <li key={p.id}>{p.title}</li>)}
    </ul>
  );
}

