import { useState, useEffect } from "react";

const getData = () => new Promise((_, rej) => setTimeout(() => rej(new Error("server down")), 100));

export default function App() {
  const [error, setError] = useState(null);
  useEffect(() => {
    getData().catch((e) => setError(e.message));
  }, []);
  if (error) return <p id="err">Error: {error}</p>;
  return <p>Đang tải...</p>;
}
